declare(strict_types=1); require dirname(__DIR__,2).'/includes/bootstrap.php'; require_admin(); $id=(int)admin()['id']; $q=db()->prepare('SELECT id,name,username,email,status,role_id FROM admins WHERE id=?');$q->execute([$id]);$profile=$q->fetch();
if(is_post()){verify_csrf();$name=trim((string)input('name'));$email=filter_var(input('email'),FILTER_VALIDATE_EMAIL);$password=(string)input('password');$confirm=(string)input('password_confirm');if($name===''||!$email||($password!==''&&(strlen($password)<12||$password!==$confirm)))flash('error','Enter a valid name/email and matching password of at least 12 characters.');else{try{$pdo=db();$sql='UPDATE admins SET name=?,email=?';$params=[$name,$email];if($password!==''){$sql.=',password_hash=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=',updated_at=NOW() WHERE id=?';$params[]=$id;$pdo->prepare($sql)->execute($params);audit_log($id,'ADMIN_PROFILE_UPDATED','admins',(string)$id,null,['password_changed'=>$password!=='']);flash('success','Profile updated successfully.');}catch(Throwable $e){flash('error','Could not update profile. Email may already exist.');}}redirect('/admin/admins/profile.php');}
$pageTitle='My profile';$pageSubtitle='Update your Super Admin account details';require APP_ROOT.'/includes/header.php';?><section class="panel"><div class="panel-head"><div><h2>Profile details</h2><p class="help">Username, role and account status are controlled by the security system.</p></div><span class="badge active"><?=e($profile['status'])?></span></div><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Full name</label><input name="name" value="<?=e($profile['name'])?>" maxlength="120" required></div><div class="field"><label>Username</label><input value="<?=e($profile['username'])?>" disabled></div><div class="field"><label>Email address</label><input name="email" type="email" value="<?=e($profile['email'])?>" required></div><div class="field"><label>Role</label><input value="Super Admin" disabled></div><div class="field"><label>New password</label><input name="password" type="password" minlength="12" autocomplete="new-password"><small class="help">Leave blank to keep your current password.</small></div><div class="field"><label>Confirm new password</label><input name="password_confirm" type="password" minlength="12" autocomplete="new-password"></div><div class="field full"><button class="btn" type="submit">Save profile</button></div></form></section><?php require APP_ROOT.'/includes/footer.php';
